class RequireApiKey:
    def __init__(self, app, header="X-Api-Key"):
        self.app, self.header = app, header

    def __call__(self, environ, start_response):
        if not environ.get(f"HTTP_{self.header.upper().replace('-', '_')}"):
            start_response("401 Unauthorized", [])
            return [b""]                           # short-circuit
        return self.app(environ, start_response)   # forward
